@startuml

class Movie {
  + Title : string
}

class Order {
  + orderDate : date
}

class User {
  + name : string
}

class Subscriber {
  + cardBalance : float
}

class Card {
  + cardNumber : string
  + balance : float
}

User "1" -- "*" Order : places
User "1" -- "0..1" Subscriber : is a
Subscriber "1" -- "1" Card : has

Order "*" -- "1" Movie : contains

@enduml

